// rc_flow.c - generated by split_c.py from RayCaster.c
#include "rc_priv.h"



//*****************************************************************************
// Run / level flow
//*****************************************************************************
void rc_ResetRun(void)
{
    uint16_t i;

    rc_hp = rc_maxHp = RC_START_HEARTS;
    rc_gold = 0;
    rc_kills = 0;
    rc_lvDmg = rc_lvRate = rc_lvSpeed = rc_lvGold = 0;
    rc_traits = 0;
    rc_staffOwned = 1;
    rc_itemOwned  = 0;
    rc_equip = 0;
    for(i = 0; i < NUM_SLOT; i++) { rc_cd[i] = 0; rc_cdMax[i] = 0; }
    rc_haste = rc_aegis = 0;
    rc_xp = 0;
    rc_xpLv = 1;
    rc_lvPending = 0;
    rc_mana = MANA_MAX;
    rc_manaAcc = rc_manaFlash = 0;
    rc_manaShown = -1;
    rc_pSlow = rc_nullify = rc_pull = 0;
    rc_miniKills = rc_miniAlive = rc_miniPending = 0;
    rc_lastMini = 0xFFFFu;
    rc_dragonKills = 0;
    rc_chestTimer = 0;
    rc_lastMap = 0xFFFFu;
    rc_wLoaded = 0xFFFFu;
}


static void MakeLevelDef(uint16_t d, LevelDef *o, bool dragon, bool treasure)
{
    uint16_t t;

    o->boss     = dragon ? 1u : 0u;
    o->treasure = treasure ? 1u : 0u;

    t = (uint16_t)(8u + 3u * d);                // more enemies each room
    if(t > 70u) t = 70u;
    o->total = dragon ? 1u : treasure ? 0u : t;

    t = (uint16_t)(4u + d / 2u);                // more at once
    if(t > 10u) t = 10u;
    o->maxAlive = t;

    o->gap = (d >= 14u) ? 18u : (uint16_t)(60u - 3u * d);   // faster arrivals
}


// A new round starts without touching the map: only the wave numbers change.
//   * every 2nd round a mini-boss joins the wave (one at a time)
//   * round 5, 15, 25 ... is a treasure round (a chest, 1 in 4 is a Mimic)
//   * the Dragon round comes once 3 mini-bosses are beaten and all 6 doors are bought
static void StartRound(uint16_t r)
{
    bool dragon   = (rc_miniKills >= RC_DRAGON_MINIS) && (rc_doorsBought >= 6u) && !rc_bossAlive;
    bool treasure = !dragon && (((r + 1u) % 10u) == RC_TREASURE_AT);

    rc_level = r;
    MakeLevelDef(r, &rc_lv, dragon, treasure);
    rc_toSpawn     = rc_lv.total;
    rc_spawnTimer  = 45;
    rc_bossSpawned = rc_bossAlive = 0;
    rc_roundGap    = 0;
    rc_miniPending = (!dragon && !treasure && ((r + 1u) % RC_MINI_EVERY) == 0u && rc_miniAlive == 0u) ? 1u : 0u;
    rc_chestTimer  = 0;

    if(dragon && !rc_doorBought[7])             // the Dragon Den door opens by itself
    {
        uint16_t mi;
        rc_doorBought[7] = true;
        rc_secOpen[6] = true;
        for(mi = 0; mi < RC_MAP_CELLS; mi++)
            if(rc_kMaps[0][mi >> RC_MAP_SHIFT][mi & (RC_MAP_W - 1u)] == '7') rc_tile[mi] = 0;
        rc_flowTx = -1; rc_flowTy = -1;
        rc_viewDirty = 2;
        rc_doorShown = 0xFFFFu;
    }
    if(treasure) rc_StartTreasure();
    rc_hud        |= HUD_TOPR | HUD_LEFT;
    if(r > 0u) rc_Sfx(&sfx_level_up);
}


// New run: load the ring map, lock every door, start round 1.
void rc_StartLevel(uint16_t lv)
{
    uint16_t i;

    rc_LoadMap();

    for(i = 0; i < RC_MAX_ENEMIES; i++) rc_en[i].alive = 0;
    for(i = 0; i < RC_MAX_OBJ; i++)     rc_obj[i].alive = 0;
    for(i = 0; i < RC_NUM_SECTIONS; i++) rc_secOpen[i] = (i == SEC_START);
    for(i = 0; i <= RC_NUM_DOORS; i++)   rc_doorBought[i] = false;
    rc_doorsBought = 0;
    rc_doorNear    = 0;
    rc_doorShown   = 0xFFFFu;
    rc_flowTx      = -1;
    rc_alive       = 0;
    rc_spawnIdx    = 0;

    StartRound(lv);
    rc_spawnTimer = 90;

    rc_ang    = 256;                     // face "down" the map: door 6 is right there
    rc_invuln = 60;
    rc_fxTimer = 0;
    rc_stepAcc = 0;

    rc_mode      = MODE_INTRO;
    rc_timer     = 75;
    rc_banner    = BAN_LEVEL;
    rc_dirtyFull = true;
}


void rc_EnterOver(void)
{
    rc_mode      = MODE_OVER;
    rc_dirtyFull = true;
    rc_Sfx(&sfx_game_over);
}


// Which closed door (if any) is the player facing and close to?
static void UpdateDoorNear(void)
{
    uint16_t k, best = 0;
    int16_t  bestD = 32767, dx, dy, d;
    int32_t  fwd;
    uint16_t key;

    for(k = 1; k <= RC_NUM_DOORS; k++)
    {
        if(k == 7u) continue;                 // arena gate is opened by the second boss milestone
        if(rc_doorBought[k]) continue;
        dx = (int16_t)(rc_doorCx[k] - rc_px);
        dy = (int16_t)(rc_doorCy[k] - rc_py);
        d  = Dist10(dx, dy);
        if(d >= DOOR_USE_DIST || d >= bestD) continue;
        fwd = (((int32_t)dx * COS(rc_ang)) + ((int32_t)dy * SIN(rc_ang))) >> 14;
        if(fwd * 10L < (int32_t)d * 6L) continue;       // must be roughly in front
        best  = k;
        bestD = d;
    }

    rc_doorNear = best;
    key = (uint16_t)(best ? (best * 2u + ((rc_gold >= rc_DoorCost()) ? 1u : 0u)) : 0u);
    if(key != rc_doorShown)
    {
        rc_doorShown = key;
        rc_hud      |= HUD_HINT;
    }
}


// Treasure round: done once the chest is opened, the Mimic is dead, or 30 s are up.
static bool TreasureDone(void)
{
    uint16_t i;
    bool     any = false;

    if(rc_chestTimer && --rc_chestTimer == 0)       // too slow: the chest vanishes
    {
        for(i = 0; i < RC_MAX_OBJ; i++)
            if(rc_obj[i].alive && rc_obj[i].kind == OB_CHEST) rc_obj[i].alive = 0;
        for(i = 0; i < RC_MAX_ENEMIES; i++)
            if(rc_en[i].alive && rc_en[i].type == ET_MIMIC) { rc_en[i].alive = 0; if(rc_alive) rc_alive--; }
        return true;
    }
    for(i = 0; i < RC_MAX_OBJ; i++)
        if(rc_obj[i].alive && rc_obj[i].kind == OB_CHEST) any = true;
    if(rc_CountType(ET_MIMIC)) any = true;
    if(!any) rc_chestTimer = 0;
    return !any;
}


static void BuyDoor(uint16_t k)
{
    uint16_t i, cost = rc_DoorCost();

    if(rc_gold < cost) { rc_Sfx(&sfx_menu_bump); return; }

    rc_gold -= cost;
    rc_doorsBought++;
    rc_doorBought[k] = true;
    for(i = 0; i < RC_MAP_CELLS; i++)                   // the doorway is now open floor
        if(rc_kMaps[0][i >> RC_MAP_SHIFT][i & (RC_MAP_W - 1u)] == (char)('0' + k)) rc_tile[i] = 0;

    if(k <= 5u)
    {
        rc_secOpen[k - 1u] = true;
        rc_secOpen[k] = true;
    }
    else if(k == 6u)
    {
        rc_secOpen[5] = true;
        rc_secOpen[0] = true;
    }

    rc_flowTx    = -1;                                   // re-path through the new opening
    rc_doorShown = 0xFFFFu;
    rc_viewDirty = 2;
    rc_hud      |= HUD_GOLD | HUD_HINT;
    rc_Sfx(&sfx_level_up);
}


void rc_UpdatePlay(void)
{
    bool    moved = false;
    int16_t jx, jy, fwd, str, c, s, mx, my, nx, ny, sp;
    uint16_t i;

    if(rc_invuln)  rc_invuln--;
    if(rc_fxTimer) rc_fxTimer--;
    if(rc_sfxHold) rc_sfxHold--;
    if(rc_stepBlock) rc_stepBlock--;
    if(rc_pSlow)   { rc_pSlow--;   if(!rc_pSlow)   rc_hud |= HUD_HINT; }
    if(rc_nullify) { rc_nullify--; if(!rc_nullify) rc_hud |= HUD_HINT; }

    for(i = 0; i < NUM_SLOT; i++)               // cooldowns (Haste ticks them twice)
    {
        if(rc_cd[i]) rc_cd[i]--;
        if(rc_haste && rc_cd[i]) rc_cd[i]--;
    }
    if(rc_haste) { rc_haste--; if(!rc_haste) rc_hud |= HUD_HINT; }
    if(rc_aegis) { rc_aegis--; if(!rc_aegis) rc_hud |= HUD_HINT; }

    // D-pad down: next staff / item
    if(g_dpad.dPressed) rc_CycleEquip();

    // Turn
    if(g_dpad.l) { rc_ang -= RC_TURN_SPEED; moved = true; }
    if(g_dpad.r) { rc_ang += RC_TURN_SPEED; moved = true; }
    rc_ang &= RC_ANGLE_MASK;

    // Move: stick up = forward, stick right = strafe right.
    jx = g_joy.dx;
    jy = RC_INVERT_Y ? g_joy.dy : (int16_t)-g_joy.dy;
    if(Abs16(jx) < RC_STICK_DEAD) jx = 0;
    if(Abs16(jy) < RC_STICK_DEAD) jy = 0;

    if(jx || jy)
    {
        sp  = (int16_t)(RC_MOVE_SPEED + ((RC_MOVE_SPEED * rc_lvSpeed) >> 3));
        if(rc_haste) sp += (int16_t)(sp >> 1);
        if(rc_pSlow) sp = (int16_t)(sp >> 1);                  // webbed / frozen
        fwd = (int16_t)(((int32_t)jy * sp * 41L) >> 12);        // stick/100 * speed
        str = (int16_t)(((int32_t)jx * sp * 41L) >> 12);
        c   = COS(rc_ang);
        s   = SIN(rc_ang);
        mx  = (int16_t)((((int32_t)fwd * c) - ((int32_t)str * s)) >> 14);
        my  = (int16_t)((((int32_t)fwd * s) + ((int32_t)str * c)) >> 14);

        nx = rc_px + mx;
        if(!Blocked(nx, rc_py, RC_PLAYER_R)) { rc_px = nx; moved = true; rc_stepAcc += (uint16_t)Abs16(mx); }
        ny = rc_py + my;
        if(!Blocked(rc_px, ny, RC_PLAYER_R)) { rc_py = ny; moved = true; rc_stepAcc += (uint16_t)Abs16(my); }
    }

#if RC_FOOTSTEPS
    // Footsteps: one rustle per RC_STEP_DIST walked, left/right alternate.
    if(rc_stepAcc >= RC_STEP_DIST)
    {
        rc_stepAcc -= RC_STEP_DIST;
        if(rc_stepAcc >= RC_STEP_DIST) rc_stepAcc = 0;        // e.g. after a long pause
        if(rc_mode == MODE_PLAY && rc_stepBlock == 0)
            Buzzer_PlaySfx(rc_stepAlt ? &sfx_step_b : &sfx_step_a);
        rc_stepAlt ^= 1u;
    }
#endif

    // The Beholder's gravity eye drags you toward it
    if(rc_pull)
    {
        int16_t gx = (int16_t)(rc_pullX - rc_px), gy = (int16_t)(rc_pullY - rc_py), gd = Dist10(gx, gy);

        rc_pull--;
        if(gd > 600)
        {
            rc_PlayerPush((int16_t)(((int32_t)gx * 24L) / gd), (int16_t)(((int32_t)gy * 24L) / gd));
            moved = true;
        }
    }

    // Mana refills slowly while the stick is released (turning still counts as standing)
    if(jx || jy)
        rc_manaAcc = 0;
    else if(!rc_nullify && rc_mana < MANA_MAX && ++rc_manaAcc >= MANA_REGEN_FRAMES)
    {
        rc_manaAcc = 0;
        rc_mana++;
    }

    // Doors: face one and press the stick to buy it
    UpdateDoorNear();
    if(g_joy.btnPressed && rc_doorNear) BuyDoor(rc_doorNear);

    // Use the equipped staff / item (hold = auto-use)
    if(g_dpad.u) rc_UseEquipped();

    rc_EnsureFlow();
    rc_UpdateObjects();
    rc_UpdateEnemies();
    rc_TrySpawn();

    // Rounds never stop: a short breather, then the next wave starts by itself.
    if(rc_mode == MODE_PLAY)
    {
        if(rc_roundGap == 0)
        {
            bool cleared;

            if(rc_lv.boss)           cleared = (rc_bossSpawned && !rc_bossAlive);
            else if(rc_lv.treasure)  cleared = TreasureDone();
            else                     cleared = (rc_toSpawn == 0 && rc_CountRegular() == 0 && !rc_miniPending);
            if(cleared)
            {
                rc_roundGap = ROUND_GAP_FRAMES;
                rc_hud     |= HUD_LEFT;
                rc_Sfx(&sfx_level_up);
            }
        }
        else if(--rc_roundGap == 0)
            StartRound(rc_level + 1u);
        else if((rc_roundGap % 30u) == 0)
            rc_hud |= HUD_LEFT;
    }

    if(moved || rc_alive || rc_fxTimer || rc_haste || rc_aegis)
        rc_viewDirty = 2;
    else
    {
        for(i = 0; i < RC_MAX_OBJ; i++)
            if(rc_obj[i].alive) { rc_viewDirty = 2; break; }
    }
}
